def handle(query, state):
    import shlex

    file_param = (query.get('file') or [''])[0].strip()
    fmt_param  = (query.get('format') or ['txt'])[0].strip()

    if not file_param:
        return 400, {'Content-Type': 'text/plain'}, 'Missing required parameter: file'

    # Simulated in-memory command executor.
    # Supports: convert <src> --to <fmt>  and  cat <path>
    # The server naively interpolates user input into the command string.
    cmd_string = 'convert {} --to {}'.format(file_param, fmt_param)

    files = state.get('files', {})
    output_parts = []

    # Split on ';' to handle command chaining (the injection point)
    for raw_cmd in cmd_string.split(';'):
        tokens = shlex.split(raw_cmd.strip()) if raw_cmd.strip() else []
        if not tokens:
            continue
        verb = tokens[0]

        if verb == 'convert':
            # convert <src> --to <fmt>
            if len(tokens) < 4 or tokens[2] != '--to':
                output_parts.append('convert: usage: convert <src> --to <fmt>')
                continue
            src = tokens[1]
            dst_fmt = tokens[3]
            content = files.get(src)
            if content is None:
                output_parts.append('convert: file not found: {}'.format(src))
            else:
                output_parts.append('[{}] {}'.format(dst_fmt.upper(), content))

        elif verb == 'cat':
            if len(tokens) < 2:
                output_parts.append('cat: missing operand')
                continue
            path = tokens[1]
            content = files.get(path)
            if content is None:
                output_parts.append('cat: {}: No such file or directory'.format(path))
            else:
                output_parts.append(content)

        elif verb == 'ls':
            output_parts.append('\n'.join(files.keys()))

        else:
            output_parts.append('{}: command not found'.format(verb))

    body = '\n'.join(output_parts)
    return 200, {'Content-Type': 'text/plain'}, body
